script:
(function () {
  'use strict';
  // Time value of money solver. With n payment periods, i = interest per period and payments at the
  // end (due = 0) or start (due = 1) of each period, the five values always balance:
  //   PV(1 + i)^n + PMT(1 + i x due)[((1 + i)^n - 1) / i] + FV = 0
  // (cash out negative, cash in positive). FV, PV and PMT are solved in closed form, n with logs:
  //   (1 + i)^n = (PMT' - FV i) / (PMT' + PV i), PMT' = PMT(1 + i x due),
  // and the rate by scanning for a sign change and bisecting. i = (1 + r/c)^(c/p) - 1 for c
  // compounding periods and p payments a year; a solved i is converted back to the annual rate r.
  // Checked in Node (five.test.js): -$10,000 now and -$200 a month at 6% for 20 years -> FV
  // $125,510.22 (10000 x 1.005^240 + 200 x (1.005^240 - 1)/0.005); $300,000 loan at 6% for 30 years
  // -> -$1,798.65 a month (standard mortgage table); solving back from -1,798.65 gives 6% and 30 years (to 2 decimals);
  // PV of $10,000 in 10 years at 5% compounded yearly = -$6,139.13; payments at the start of the
  // period: -$1,000 a year at 5% for 10 years -> $13,206.79 (annuity due); 0% rate -> plain sums.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var MODES = ['fv', 'pv', 'pmt', 'rate', 'years'];
  var RADIOS = { fv: 'fnSolveFv', pv: 'fnSolvePv', pmt: 'fnSolvePmt', rate: 'fnSolveRate', years: 'fnSolveYears' };
  var FIELDS = { fv: 'fnFvField', pv: 'fnPvField', pmt: 'fnPmtField', rate: 'fnRateField', years: 'fnYearsField' };
  var FREQ_WORD = { 52: 'Weekly', 26: 'Biweekly', 12: 'Monthly', 4: 'Quarterly', 2: 'Semiannual', 1: 'Yearly' };
  var OUTPUTS = ['fnAnswer', 'fnTotalPmt', 'fnTotalInt', 'fnPvOut', 'fnPmtOut', 'fnFvOut', 'fnRateOut', 'fnTimeOut', 'fnEarOut'];
  var MAX_SCHEDULE_YEARS = 100;

  // --- calc start
  function annuity(i, n, due) {
    var f = Math.abs(i) < 1e-12 ? n : (Math.pow(1 + i, n) - 1) / i;
    return due ? f * (1 + i) : f;
  }
  function tvm(n, i, pv, pmt, fv, due) { return pv * Math.pow(1 + i, n) + pmt * annuity(i, n, due) + fv; }
  function solveFv(n, i, pv, pmt, due) { return -(pv * Math.pow(1 + i, n) + pmt * annuity(i, n, due)); }
  function solvePv(n, i, pmt, fv, due) { return -(fv + pmt * annuity(i, n, due)) / Math.pow(1 + i, n); }
  function solvePmt(n, i, pv, fv, due) {
    var a = annuity(i, n, due);
    return a === 0 ? NaN : -(pv * Math.pow(1 + i, n) + fv) / a;
  }
  function solveN(i, pv, pmt, fv, due) {
    if (Math.abs(i) < 1e-12) return pmt === 0 ? NaN : -(pv + fv) / pmt;
    var p = pmt * (due ? 1 + i : 1), top = p - fv * i, bottom = p + pv * i;
    if (bottom === 0 || top / bottom <= 0) return NaN;
    return Math.log(top / bottom) / Math.log(1 + i);
  }
  // Per-period rate: scan a grid from -99% to +1000% per period for sign changes, bisect each,
  // and return the root closest to zero (the usual answer when more than one exists).
  function solveRate(n, pv, pmt, fv, due) {
    var grid = [-0.99], k, best = NaN;
    for (k = -0.99; k < -1e-6; k = k * 0.9) grid.push(k);
    for (k = -1e-6; k < 10; k = k < 0 ? 1e-6 : k * 1.1) grid.push(k);
    grid.push(10);
    for (var g = 1; g < grid.length; g++) {
      var a = grid[g - 1], b = grid[g], fa = tvm(n, a, pv, pmt, fv, due), fb = tvm(n, b, pv, pmt, fv, due);
      if (!isFinite(fa) || !isFinite(fb)) continue;
      var root = NaN;
      if (fa === 0) root = a;
      else if (fa * fb < 0) {
        for (var it = 0; it < 200; it++) {
          var mid = (a + b) / 2, fm = tvm(n, mid, pv, pmt, fv, due);
          if (fm === 0) { a = b = mid; break; }
          if (fa * fm < 0) b = mid; else { a = mid; fa = fm; }
        }
        root = (a + b) / 2;
      }
      if (!isNaN(root) && (isNaN(best) || Math.abs(root) < Math.abs(best))) best = root;
    }
    return best;
  }
  function periodRate(r, comp, perYear) { return Math.pow(1 + r / comp, comp / perYear) - 1; }
  function annualRate(i, comp, perYear) { return comp * (Math.pow(1 + i, perYear / comp) - 1); }
  // Balance after each period (same sign as PV), grouped into rows of perYear periods.
  function schedule(n, i, pv, pmt, due, perYear) {
    var bal = pv, rows = [], yP = 0, yI = 0, whole = Math.floor(n + 1e-9);
    for (var k = 1; k <= whole; k++) {
      var g;
      if (due) { bal += pmt; g = bal * i; bal += g; } else { g = bal * i; bal += g + pmt; }
      yP += pmt; yI += g;
      if (k % perYear === 0 || k === whole) { rows.push({ year: Math.ceil(k / perYear), part: k % perYear !== 0, pmt: yP, int: yI, bal: bal }); yP = 0; yI = 0; }
    }
    return rows;
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function fmt(x, digits) { return x.toFixed(digits).replace(/\.?0+$/, ''); }

  function mode() {
    for (var k = 0; k < MODES.length; k++) if (document.getElementById(RADIOS[MODES[k]]).checked) return MODES[k];
    return 'fv';
  }

  function fail(msg) {
    var error = document.getElementById('fnError');
    error.hidden = false;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { document.getElementById(id).textContent = '–'; });
    document.getElementById('fnSchedule').innerHTML = '';
  }

  function update() {
    var solve = mode();
    MODES.forEach(function (m) { document.getElementById(FIELDS[m]).hidden = m === solve; });
    var perYear = parseInt(document.getElementById('fnFreq').value, 10);
    var compVal = document.getElementById('fnComp').value;
    var comp = compVal === 'same' ? perYear : parseInt(compVal, 10);
    var due = document.getElementById('fnTiming').value === 'begin';
    var pmtWord = FREQ_WORD[perYear] + ' payment';
    document.getElementById('fnPmtLabel').textContent = pmtWord;
    document.getElementById('fnPmtOutLabel').textContent = pmtWord;
    var labels = { fv: 'Future value', pv: 'Starting amount (present value)', pmt: pmtWord, rate: 'Annual interest rate', years: 'Number of years' };
    document.getElementById('fnAnswerLabel').textContent = labels[solve];
    var note = document.getElementById('fnNote');
    note.hidden = true;
    document.getElementById('fnError').hidden = true;

    var pv = num('fnPv'), pmt = num('fnPmt'), fv = num('fnFv'), rate = num('fnRate'), years = num('fnYears');
    var need = { fv: [pv, pmt, rate, years], pv: [pmt, fv, rate, years], pmt: [pv, fv, rate, years],
                 rate: [pv, pmt, fv, years], years: [pv, pmt, fv, rate] }[solve];
    if (need.some(isNaN)) return fail('Fill in every visible field with a number (use 0 where it does not apply).');
    if (solve !== 'rate' && (rate < 0 || rate > 100)) return fail('Enter an annual interest rate from 0 to 100%.');
    if (solve !== 'years' && (years <= 0 || years > 100)) return fail('Enter a number of years above 0 and up to 100.');

    var i = solve === 'rate' ? NaN : periodRate(rate / 100, comp, perYear);
    var n = years * perYear;
    if (solve === 'fv') fv = solveFv(n, i, pv, pmt, due);
    else if (solve === 'pv') pv = solvePv(n, i, pmt, fv, due);
    else if (solve === 'pmt') {
      pmt = solvePmt(n, i, pv, fv, due);
    } else if (solve === 'rate') {
      if (pv === 0 && pmt === 0) return fail('Enter a starting amount, a payment or both.');
      i = solveRate(n, pv, pmt, fv, due);
      if (isNaN(i)) return fail('No interest rate balances these amounts. Check the signs: at least one amount must be money you pay (negative) and one money you receive (positive).');
      rate = annualRate(i, comp, perYear) * 100;
    } else {
      n = solveN(i, pv, pmt, fv, due);
      if (!isFinite(n) || n <= 0) return fail('These amounts never balance. Check the signs: money you pay is negative, money you receive is positive, and the payment must be large enough to make progress.');
      years = n / perYear;
      if (years > 1000) return fail('That would take more than 1,000 years.');
    }
    if (![pv, pmt, fv, i, n].every(isFinite) || Math.max(Math.abs(pv), Math.abs(pmt), Math.abs(fv)) > 1e15) return fail('That result is too large to show. Try smaller numbers.');

    var totalPmt = pmt * n, totalInt = Math.abs(pv + totalPmt + fv);
    var timeText = fmt(years, 2) + (Math.abs(years - 1) < 1e-9 ? ' year' : ' years') + ' (' + fmt(n, 2) + ' payments)';
    var rateText = fmt(rate, 4) + '%';
    var answer = { fv: money.format(fv), pv: money.format(pv), pmt: money.format(pmt), rate: rateText, years: fmt(years, 2) + ' years' }[solve];
    document.getElementById('fnAnswer').textContent = answer;
    document.getElementById('fnTotalPmt').textContent = money.format(totalPmt);
    document.getElementById('fnTotalInt').textContent = money.format(totalInt);
    document.getElementById('fnPvOut').textContent = money.format(pv);
    document.getElementById('fnPmtOut').textContent = money.format(pmt);
    document.getElementById('fnFvOut').textContent = money.format(fv);
    document.getElementById('fnRateOut').textContent = rateText;
    document.getElementById('fnTimeOut').textContent = timeText;
    document.getElementById('fnEarOut').textContent = fmt((Math.pow(1 + i, perYear) - 1) * 100, 4) + '%';

    var notes = [];
    if (Math.abs(n - Math.round(n)) > 1e-6) notes.push('The number of payments is not a whole number, so the last payment would be a smaller, partial one. The schedule shows the full payments only.');
    if (solve === 'rate' && rate < 0) notes.push('The rate is negative: you get back less than you put in.');
    var rows = schedule(Math.min(n, MAX_SCHEDULE_YEARS * perYear), i, pv, pmt, due, perYear);
    if (years > MAX_SCHEDULE_YEARS) notes.push('The schedule shows the first 100 years.');
    if (notes.length) { note.hidden = false; note.textContent = notes.join(' '); }
    document.getElementById('fnSchedule').innerHTML = rows.map(function (row) {
      return '<tr><td>' + row.year + (row.part ? ' (part)' : '') + '</td><td>' + money.format(Math.abs(row.pmt)) + '</td><td>' +
             money.format(Math.abs(row.int)) + '</td><td>' + money.format(Math.abs(row.bal)) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('fnForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
